import{_ as r,D as s,o as i,c,m as l,a as t,G as a,S as d}from"./chunks/framework.DuIEtbrD.js";const P=JSON.parse('{"title":"现代浏览器架构","description":"通过了解浏览器的多进程模型、渲染管线以及事件循环，开发者可以更有效地编写高效、稳定且用户体验优秀的应用，同时避免常见的性能瓶颈和错误，从而提升整体开发水平","frontmatter":{"title":"现代浏览器架构","description":"通过了解浏览器的多进程模型、渲染管线以及事件循环，开发者可以更有效地编写高效、稳定且用户体验优秀的应用，同时避免常见的性能瓶颈和错误，从而提升整体开发水平","keywords":"Chrome,浏览器,浏览器架构,Webkit,Blink,Gecko,EdgeHTML,Chromium,渲染引擎,沙盒隔离,网站隔离,多进程,多线程,进程通信,浏览器面试,Safari,Firefox","logo":"https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/icon-browser.png"},"headers":[],"relativePath":"frontend/browser/base.md","filePath":"frontend/browser/base.md","lastUpdated":1776945570000}'),h={name:"frontend/browser/base.md"};function u(D,e,m,b,y,F){const o=s("Obsolete"),n=s("Reward"),p=s("Gitalk");return i(),c("div",null,[e[0]||(e[0]=l("h1",{id:"现代浏览器架构",tabindex:"-1"},[t("现代浏览器架构 "),l("a",{class:"header-anchor",href:"#现代浏览器架构","aria-label":'Permalink to "现代浏览器架构"'},"​")],-1)),a(o,{date:"2021-06-19"}),e[1]||(e[1]=d(`<p>在互联网高速发展的今天，浏览器已成为用户与网络世界连接的核心工具。从简单的文档查看器演变而来，现代浏览器不仅要快速解析网页，还需同时支持复杂的多媒体内容、交互式应用以及高性能的后台任务。为了满足这些需求，浏览器的架构变得愈发复杂且精妙——它们采用模块化、多进程和安全优先的设计，以提升性能、稳定性和安全性</p><p>本文将以“现代浏览器架构 - Chrome”为核心，探讨其背后的设计理念、工作流程以及各关键组件的职责，揭示这一网络时代基础设施如何高效运作、应对复杂挑战，并为开发者与用户提供卓越的体验</p><h2 id="cpu和gpu" tabindex="-1">CPU和GPU <a class="header-anchor" href="#cpu和gpu" aria-label="Permalink to &quot;CPU和GPU&quot;">​</a></h2><p><code>CPU（Central Processing Unit，中央处理器）</code> 是计算机的大脑，负责执行所有的计算任务和控制操作。它是计算机中最核心的部分，决定了系统的运算速度和能力</p><p>CPU 核心（如图中描述的办公室员工）可以处理许多不同的任务 逐一查看这些状态信息它能处理数学、美术等各种任务，而且知道如何回复 。过去，大多数 CPU 都是单芯片。核心就像是生活在 同一条状标签。在现代硬件中，您通常会获得多个核心，从而提供更好的计算能力 添加到手机和笔记本电脑上</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/cpu-fc96f4ee3715f_1440.png" alt=""></p><p><code>GPU（Graphics Processing Unit，图形处理器）</code> 是专门用于处理图形和并行计算的硬件单元。最初，GPU 主要用来加速图形渲染，但如今已广泛用于机器学习、科学计算等需要并行处理的场景。</p><p>图像处理与 CPU 不同 GPU 擅长处理简单的任务，但可以同时跨多个核心。它最初是为了处理图形而开发的。这就是为什么 &quot;使用 GPU&quot;或“支持 GPU”与快速渲染和流畅交互有关。 近年来，随着 GPU 加速计算的推出，越来越多的计算可以在 仅使用 GPU</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/gpu-ff4b6081ab9b1_1440.png" alt=""></p><p>CPU 和 GPU 是计算机中两种核心处理单元，各自擅长不同类型的任务。CPU 提供强大的通用计算能力，适合执行单一线程为主的任务；而 GPU 的多核心架构则使其在需要大量并行计算的任务中表现卓越。这两者相辅相成，共同构成现代计算设备的强大性能基础</p><h2 id="进程和线程" tabindex="-1">进程和线程 <a class="header-anchor" href="#进程和线程" aria-label="Permalink to &quot;进程和线程&quot;">​</a></h2><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/process-threads-6fe2ce3d7b3e2_1440.png" alt=""></p><p><code>进程（Process）</code> 是操作系统中独立运行的程序实例。它是一个具有独立资源和内存空间的执行单元，代表了一个正在运行的应用或任务</p><p><code>线程（Thread）</code> 是进程中的最小执行单元。一个进程可以包含一个或多个线程，这些线程共享进程的内存空间和资源</p><p>启动应用时，系统会创建一个进程。程序可能会创建线程来帮助它 可以运行，但这是可选操作。操作系统为这一过程提供了一个“平台”运行 并且所有应用状态都保存在该私有内存空间中关闭 该进程也会停止，操作系统也会释放内存</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/process-memory-60ff42694f726.svg" alt=""></p><p>进程可要求操作系统启动另一个进程以运行不同的任务。当 内存的不同部分会分配给新进程如果两个进程需要 谈话时，他们可以使用私密通信 (IPC) 来实现。许多应用 按照这种方式工作，如果工作器进程无响应，可以将其重启 而无需停止运行应用不同部分的其他进程</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/worker-process-ipc-ea8392115a438.svg" alt=""></p><h2 id="浏览器架构" tabindex="-1">浏览器架构 <a class="header-anchor" href="#浏览器架构" aria-label="Permalink to &quot;浏览器架构&quot;">​</a></h2><p>Chrome 浏览器采用了<code>多进程、多线程</code>架构，这种设计旨在实现更高的性能、稳定性和安全性。通过进程与线程的合理划分，Chrome 能够高效地处理用户操作、页面渲染和后台任务</p><p>Chrome 的架构既包含多个独立的进程，也在每个进程内运行多个线程。主要组件和职责如下：</p><h3 id="多进程架构" tabindex="-1">多进程架构 <a class="header-anchor" href="#多进程架构" aria-label="Permalink to &quot;多进程架构&quot;">​</a></h3><ul><li><p><code>浏览器进程（Browser Process）</code>：</p><ul><li>唯一的主进程，负责浏览器的整体协调</li><li>主要功能： <ul><li>管理用户界面（地址栏、书签栏、标签管理等）</li><li>网络请求（发起 HTTP 请求并接收响应）</li><li>管理文件和存储</li><li>控制和分配其他进程</li></ul></li></ul></li><li><p><code>渲染进程（Renderer Process）</code>：</p><ul><li>多实例：每个标签页通常对应一个渲染进程（也可能多个页面共享同一进程，取决于浏览器的优化策略，如：<u>页面中点击打开同域新页面会共享一个渲染进程</u>）</li><li>主要功能： <ul><li>执行 HTML、CSS、JavaScript</li><li>构建 DOM 树、CSSOM 树并渲染页面</li><li>沙盒隔离，限制操作系统的直接访问</li></ul></li></ul></li><li><p><code>GPU 进程（GPU Process）</code>：</p><ul><li>全局唯一，负责硬件加速任务</li><li>提供 2D/3D 图形渲染的支持，如 WebGL、Canvas 和视频解码</li></ul></li><li><p><code>插件进程（Plugin Process）</code>：</p><ul><li>独立于渲染进程，用于运行浏览器插件（如 Flash）</li><li>每个插件运行在自己的进程中，避免插件崩溃影响浏览器</li></ul></li><li><p><code>扩展进程（Extension Process）</code>：每个扩展运行在独立的进程中，提高浏览器的稳定性</p></li></ul><h3 id="多线程架构" tabindex="-1">多线程架构 <a class="header-anchor" href="#多线程架构" aria-label="Permalink to &quot;多线程架构&quot;">​</a></h3><p>每个进程内部进一步包含多个线程，主要线程及其职责如下：</p><p>浏览器进程的线程</p><ul><li><code>主线程</code>：负责用户界面和其他核心逻辑</li><li><code>网络线程</code>：处理所有网络相关任务（如 HTTP 请求和响应）</li><li><code>存储线程</code>：负责管理本地存储、缓存和数据库（如 IndexedDB）</li><li><code>文件线程</code>：处理文件读写任务</li></ul><p>渲染进程的线程</p><ul><li><code>主线程</code>：处理 DOM 操作、页面布局和 JavaScript 执行</li><li><code>合成线程（Compositor Thread）</code>： <ul><li>负责页面渲染的合成部分，将主线程生成的图层合成为最终显示的页面</li><li>在主线程繁忙时，能保持页面的滚动和动画流畅</li></ul></li><li><code>光栅化线程（Rasterization Thread）</code>：使用 GPU 加速绘制页面内容，将图层绘制为位图</li><li><code>工作线程（Worker Threads</code>）：执行 Web Worker 和 Service Worker 等后台任务</li></ul><h2 id="为什么要多进程" tabindex="-1">为什么要多进程 <a class="header-anchor" href="#为什么要多进程" aria-label="Permalink to &quot;为什么要多进程&quot;">​</a></h2><p>Chrome 浏览器采用了多进程架构，将浏览器的不同功能模块（如 UI、渲染、插件、扩展等）分配到独立的进程中运行。相比传统的单进程架构，这种设计具有以下显著优势</p><h3 id="稳定性" tabindex="-1">稳定性 <a class="header-anchor" href="#稳定性" aria-label="Permalink to &quot;稳定性&quot;">​</a></h3><p>在一个标签页加载一个占用大量资源的网页（如复杂的动画或错误的脚本），即使其崩溃，也不会中断其他标签页的正常使用</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/multiple-renderer-tabs-c29a1fd34d4d_1440.png" alt=""></p><p>如果某个标签页无响应，您可以关闭无响应的标签页并继续操作，同时保持 其他标签页处于活动状态如果所有标签页都在一个进程中运行，那么当一个标签页无响应时，所有标签页 标签页无响应太可惜了</p><h3 id="安全性-网站隔离" tabindex="-1">安全性 - 网站隔离 <a class="header-anchor" href="#安全性-网站隔离" aria-label="Permalink to &quot;安全性 - 网站隔离&quot;">​</a></h3><p>访问含有恶意脚本的页面时，由于渲染进程被隔离，该脚本无法访问用户的文件或其他页面的数据</p><blockquote><p>渲染进程运行在沙盒中，被严格限制对文件系统、设备和操作系统资源的访问</p></blockquote><p><a href="https://developers.google.com/web/updates/2018/07/site-isolation?hl=zh-cn" target="_blank" rel="noreferrer">网站隔离</a> 是最近 在 Chrome 中引入了一项功能，可<u>为每个跨网站 iframe 运行单独的渲染程序进程</u></p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/site-isolation-2521dc96bb823_1440.png" alt=""></p><p>我们一直在介绍每个标签页模型一个渲染程序进程，该模式允许跨网站 在单个渲染器进程中运行的 iframe，不同网站之间共享内存空间。 在同一个渲染器进程中运行 a.com 和 b.com 似乎没有问题。 同源政策 是网络的核心安全模型；可确保一个网站无法访问来自其他网站的数据 未经同意。绕过此政策是安全攻击的主要目标。 进程隔离是分隔网站最有效的方法</p><p>从 Chrome 67 开始，在桌面设备上默认启用网站隔离功能后，标签页中的每个跨网站 iframe 会获得一个单独的渲染程序进程</p><h3 id="高效利用内存" tabindex="-1">高效利用内存 <a class="header-anchor" href="#高效利用内存" aria-label="Permalink to &quot;高效利用内存&quot;">​</a></h3><p>浏览器进程也采用同样的方法。Chrome 正在进行架构更改 将浏览器程序的各部分作为服务运行，允许拆分为不同的进程 也可以将其合并为一个应用</p><p>一般来说，当 Chrome 在功能强大的硬件上运行时，可能会将每项服务拆分为 不同的进程赋予更高的稳定性，但如果在资源受限的设备上，则 Chrome 将服务整合到一个进程中，从而节省内存。类似的整合方法 在此次变更之前，Android 等平台上都使用了内存使用量较少的进程</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/chrome-servification-f06f547c54405.svg" alt=""></p><h2 id="浏览器内核" tabindex="-1">浏览器内核 <a class="header-anchor" href="#浏览器内核" aria-label="Permalink to &quot;浏览器内核&quot;">​</a></h2><p>浏览器内核是浏览器的核心组件，负责浏览器与操作系统的交互、网页资源的加载、以及管理和调度其他内核模块（如渲染引擎、JavaScript 引擎、网络模块等）。它是浏览器的基础架构，保证了浏览器能够处理网页的渲染、交互和其他功能</p><p>不同的浏览器内核实现方式不同，常见的浏览器内核有：</p><ul><li><code>Chromium 内核（Blink）</code>：这是 Google Chrome、Microsoft Edge、Opera 等浏览器的基础内核。Chromium 是一个开源项目，而 Blink 是 Chromium 项目中的渲染引擎</li><li><code>Gecko 内核</code>：Mozilla Firefox 浏览器使用的内核。Gecko 渲染引擎负责网页的渲染</li><li><code>WebKit 内核</code>：Safari 浏览器使用的内核。WebKit 最初由 Apple 开发，它是一个开源项目，曾经是 Chrome 的渲染引擎（但后期 Chrome 切换到 Blink）</li><li><code>EdgeHTML 内核</code>：Microsoft Edge（在其初始版本中）使用的内核，是一个由 Microsoft 开发的渲染引擎，后来 Edge 切换到 Chromium 内核（即 Blink）</li></ul><p><strong>浏览器引擎</strong>：</p><ul><li>Chrome：v8</li><li>Firefox：SpiderMonkey</li><li>Safari：JavascriptCore(Nitro)</li><li>Edge：以前基于Chakra，后来也是v8</li></ul><h2 id="浏览器url回车后发生了什么" tabindex="-1">浏览器URL回车后发生了什么 <a class="header-anchor" href="#浏览器url回车后发生了什么" aria-label="Permalink to &quot;浏览器URL回车后发生了什么&quot;">​</a></h2><p><code>浏览器URL回车后发生了什么</code>❓这是一个老生常谈、面试高频的一个问题‼️</p><p>整个过程涉及浏览器多个进程的协调工作。每个进程负责不同的任务，确保网页能够被正确加载、渲染和展示给用户</p><ol><li><p>用户输入 URL：当你在地址栏输入 URL 后，浏览器开始进行一系列的操作来请求并显示网页</p><p><u>主进程（Browser Process）：</u></p><ul><li>解析 URL：浏览器的主进程负责解析用户输入的 URL，确定协议、域名、路径等信息</li><li>创建新的标签页进程：如果没有现有标签页在执行此请求，浏览器的主进程会创建一个新的渲染进程来处理该页面的渲染</li></ul></li><li><p>DNS 解析：浏览器需要将 URL 中的域名解析为 IP 地址，以便连接到服务器。这个过程是通过 DNS（域名系统）来完成的</p><p><u>主进程（Browser Process）和网络进程（Network Process）：</u></p><ul><li>DNS 查询：主进程会向网络进程发起 DNS 查询请求，查询域名对应的 IP 地址</li><li>查询缓存：主进程首先会检查浏览器的DNS缓存，看是否有该域名的IP地址。如果缓存中存在，就直接使用，否则发起 DNS 请求</li><li>DNS 响应：网络进程向主进程返回解析后的 IP 地址</li></ul></li><li><p>TCP 连接：一旦得到服务器的 IP 地址，浏览器需要与服务器建立 TCP 连接（对于 HTTPS，还会进行 TLS 握手）。</p><p><u>网络进程（Network Process）：</u></p><ul><li>建立连接：网络进程通过套接字（Socket）与目标 IP 地址建立 TCP 连接</li><li>TLS 握手（如果是 HTTPS）：如果 URL 使用的是 HTTPS 协议，网络进程会与服务器通过 TLS 进行加密握手，确保数据传输的安全性</li></ul></li><li><p>发送 HTTP 请求：连接建立后，浏览器将向服务器发送 HTTP 请求，获取网页内容</p><p><u>主进程（Browser Process）和网络进程（Network Process）：</u></p><ul><li>构建 HTTP 请求：主进程生成 HTTP 请求消息（如 GET 请求），包括请求头、Cookies、缓存控制等信息</li><li>发送请求：网络进程将 HTTP 请求发送到目标服务器</li></ul></li><li><p>服务器响应：服务器收到请求后，会处理并返回响应内容，浏览器开始接收响应数据</p><p><u>网络进程（Network Process）：</u></p><ul><li>接收响应：网络进程接收服务器返回的 HTTP 响应，通常包括状态码、响应头、响应体（网页内容）</li><li>缓存和存储：网络进程会根据响应头的缓存控制策略，将数据存储到缓存中，以便下次请求时可以更快地响应</li></ul></li><li><p>页面解析、绘制合成</p></li></ol><blockquote><p>文档加载完后会通知浏览器进程，tab的加载按钮就停止了；文档卸载时浏览器进程和渲染进程要进行通信确保unload事件</p></blockquote><h2 id="页面渲染过程" tabindex="-1">页面渲染过程 <a class="header-anchor" href="#页面渲染过程" aria-label="Permalink to &quot;页面渲染过程&quot;">​</a></h2><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/v2-543b927c468bb37a598fd5a16a971668_1440w.png" alt=""></p><ol><li><p><code>生成DOM树</code>：浏览器从上到下逐行解析 HTML 文本，将 HTML 标签转换成 DOM 树的节点。每个 HTML 标签都对应一个 DOM 元素；如果浏览器在解析过程中如果遇到<code>style</code>标签时会开辟新线程解析它；若遇到 <code>script</code> 标签，根据3种情况执行</p><ul><li><code>行内script</code>：暂停解析DOM并立即执行当前script</li><li><code>&lt;script defer&gt;</code>：主线程继续解析DOM，此时开辟一个新线程来加载js脚本，当文档解析完毕后，立即执行当前js脚本（脚本执行时机早于<code>ContentLoaded</code>事件）</li><li><code>&lt;script async&gt;</code>：主线程继续解析DOM，此时开辟一个新线程来加载js脚本，当文档解析完毕触发<code>ContentLoaded</code>事件后执行此脚本</li></ul></li><li><p><code>生成CSS树</code>：当浏览器遇到外部 <code>&lt;link&gt;</code> 标签或内部 <code>&lt;style&gt;</code> 标签时，会加载并解析 CSS 样式。CSS 样式会被转换为 CSSOM 树</p></li><li><p><code>生成渲染树</code>：渲染树是从 DOM 树和 CSSOM 树中筛选出可见元素并计算其样式后构建的。只有在页面中可见的元素才会出现在渲染树中。例如：<code>display: none</code> 的元素不会出现在渲染树中以及它们的样式信息</p></li><li><p><code>生成布局树(Layout)</code>：布局阶段是计算页面中每个元素的确切位置和尺寸。根据渲染树中每个节点的样式（如 width、height、margin、padding、position 等），浏览器会计算每个元素的精确位置和大小。这个过程称为 <code>Reflow</code></p></li><li><p><code>绘制(Paint)</code>：绘制过程是将布局阶段计算出的几何信息转换为实际的像素。每个元素会根据其样式（如背景色、边框、文本、阴影等）被绘制到屏幕上；一些元素可能被绘制到不同的图层上（例如，浮动元素、动画元素、固定定位的元素等）。这些层会独立地进行绘制和合成</p></li><li><p><code>合成(Compositin)</code>：合成阶段是指将各个图层合并为一个最终图像，并将其显示在屏幕上；当页面包含多个层时，浏览器会将这些层单独处理，并最终合成一个完整的图像。这个过程可能通过 GPU 加速进行，以提高性能</p></li><li><p><code>分层</code>：为了确定哪些元素需要位于哪些层，主线程会遍历布局树来创建层树（此部分在开发者工具性能面板中称为“Update Layer Tree”）。如果网页中本应属于单独图层的某些部分（例如滑入式侧边菜单）没有出现，您可以使用 CSS 中的 will-change 属性来提示浏览器</p></li><li><p><code>光栅化位图</code>：创建层树并确定绘制顺序后，主线程会将该信息提交到合成器线程。然后，合成器线程会光栅化每个图层。图层的大小可能相当于页面的全部长度，因此合成器线程会将它们分成多块图块，并将每个图块发送到光栅线程。光栅线程会光栅化每个图块并将它们存储在 GPU 内存中</p></li></ol><p>图块光栅化后，合成器线程会收集图块信息（称为“绘制四边形”）来创建合成器框架</p><p>然后，通过 IPC 将合成器帧提交到浏览器进程。此时，可以从界面线程（针对浏览器界面更改）或针对扩展程序的其他渲染程序进程添加另一个合成器帧。系统会将这些合成器帧发送到 GPU，以便在屏幕上显示。如果发生滚动事件，合成器线程会再创建一个合成器帧以发送到 GPU</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/composit-266744978ac93_1440.png" alt=""></p><blockquote><p>合成的好处是，在不涉及主线程的情况下完成。合成器线程不需要等待样式计算或 JavaScript 执行。因此，仅合成动画被认为是实现流畅性能的最佳选择。如果需要再次计算布局或绘制，则必须涉及主线程</p></blockquote><h2 id="渲染优化" tabindex="-1">渲染优化 <a class="header-anchor" href="#渲染优化" aria-label="Permalink to &quot;渲染优化&quot;">​</a></h2><p>从上文我们知道页面渲染是一个非常昂贵的过程，应尽量避免页面的重新渲染</p><h3 id="避免频繁的重排和重绘" tabindex="-1">避免频繁的重排和重绘 <a class="header-anchor" href="#避免频繁的重排和重绘" aria-label="Permalink to &quot;避免频繁的重排和重绘&quot;">​</a></h3><p><code>重排（Reflow）</code>：修改布局相关的属性或样式（如 width、height、margin） <code>重绘（Repaint）</code>：修改颜色、背景、阴影等不影响布局的样式</p><p>例如批量修改 DOM 和样式：将多次 DOM 操作合并为一次性操作、使用 DocumentFragment 进行操作：</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#676E95;font-style:italic;">// 避免多次操作 DOM</span></span>
<span class="line"><span style="color:#C792EA;">const</span><span style="color:#BABED8;"> el </span><span style="color:#89DDFF;">=</span><span style="color:#BABED8;"> document</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">getElementById</span><span style="color:#BABED8;">(</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">example</span><span style="color:#89DDFF;">&#39;</span><span style="color:#BABED8;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#BABED8;">el</span><span style="color:#89DDFF;">.</span><span style="color:#BABED8;">style</span><span style="color:#89DDFF;">.</span><span style="color:#BABED8;">width </span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">100px</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#BABED8;">el</span><span style="color:#89DDFF;">.</span><span style="color:#BABED8;">style</span><span style="color:#89DDFF;">.</span><span style="color:#BABED8;">height </span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">100px</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;">// 合并修改</span></span>
<span class="line"><span style="color:#BABED8;">el</span><span style="color:#89DDFF;">.</span><span style="color:#BABED8;">style</span><span style="color:#89DDFF;">.</span><span style="color:#BABED8;">cssText </span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">width: 100px; height: 100px;</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;">// createDocumentFragment</span></span>
<span class="line"><span style="color:#C792EA;">const</span><span style="color:#BABED8;"> fragment </span><span style="color:#89DDFF;">=</span><span style="color:#BABED8;"> document</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">createDocumentFragment</span><span style="color:#BABED8;">()</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">for</span><span style="color:#BABED8;"> (</span><span style="color:#C792EA;">let</span><span style="color:#BABED8;"> i </span><span style="color:#89DDFF;">=</span><span style="color:#F78C6C;"> 0</span><span style="color:#89DDFF;">;</span><span style="color:#BABED8;"> i </span><span style="color:#89DDFF;">&lt;</span><span style="color:#F78C6C;"> 100</span><span style="color:#89DDFF;">;</span><span style="color:#BABED8;"> i</span><span style="color:#89DDFF;">++</span><span style="color:#BABED8;">) </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#C792EA;">  const</span><span style="color:#BABED8;"> newNode</span><span style="color:#89DDFF;"> =</span><span style="color:#BABED8;"> document</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">createElement</span><span style="color:#F07178;">(</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">div</span><span style="color:#89DDFF;">&#39;</span><span style="color:#F07178;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#BABED8;">  newNode</span><span style="color:#89DDFF;">.</span><span style="color:#BABED8;">textContent</span><span style="color:#89DDFF;"> =</span><span style="color:#89DDFF;"> \`</span><span style="color:#C3E88D;">Item </span><span style="color:#89DDFF;">\${</span><span style="color:#BABED8;">i</span><span style="color:#89DDFF;">}\`</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#BABED8;">  fragment</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">appendChild</span><span style="color:#F07178;">(</span><span style="color:#BABED8;">newNode</span><span style="color:#F07178;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span>
<span class="line"><span style="color:#BABED8;">document</span><span style="color:#89DDFF;">.</span><span style="color:#BABED8;">body</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">appendChild</span><span style="color:#BABED8;">(fragment)</span><span style="color:#89DDFF;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><h3 id="分层优化" tabindex="-1">分层优化 <a class="header-anchor" href="#分层优化" aria-label="Permalink to &quot;分层优化&quot;">​</a></h3><p>减少绘制次数并提升合成效率，明确指定需要独立图层的元素，利用 GPU 加速渲染动画和滚动</p><div class="language-css line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#FFCB6B;">will-change</span><span style="color:#BABED8;">: transform</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;"> opacity;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="合成优化" tabindex="-1">合成优化 <a class="header-anchor" href="#合成优化" aria-label="Permalink to &quot;合成优化&quot;">​</a></h3><p>充分利用 GPU 加速减少 CPU 开销</p><ul><li><p>优化动画的样式，只使用 合成属性：<code>transform</code>、<code>opacity</code>、<code>will-change(最后使用)</code>；避免触发布局或绘制的动画，例如 top、left、width 和 height 的动画</p></li><li><p>为滚动区域添加 will-change: transform; 或 position: fixed;，使浏览器利用 GPU 优化滚动渲染</p></li></ul><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li><a href="https://developer.chrome.com/blog/inside-browser-part1/" target="_blank" rel="noreferrer">developer browser part1</a></li><li><a href="https://developer.chrome.com/blog/inside-browser-part2/" target="_blank" rel="noreferrer">developer browser part2</a></li><li><a href="https://developer.chrome.com/blog/inside-browser-part3/" target="_blank" rel="noreferrer">developer browser part3</a></li><li><a href="https://developer.chrome.com/blog/inside-browser-part4/" target="_blank" rel="noreferrer">developer browser part4</a></li><li><a href="https://web.dev/howbrowserswork/" target="_blank" rel="noreferrer">how browsers work</a></li></ul>`,78)),a(n),a(p)])}const f=r(h,[["render",u]]);export{P as __pageData,f as default};
